case NODE_TYPE_DECISION: {
    DecisionNodeConfig* cfg = &node->config.decision_config;
    // Simple parsing logic for "field==value"
    char field[64], value[64];
    sscanf(cfg->condition, "%[^=]==%s", field, value);

    const char* record_value = get_field_from_record(data_record, field);
    int next_node_id = -1;
    if (record_value && strcmp(record_value, value) == 0) {
        next_node_id = cfg->true_node_id;
    } else {
        next_node_id = cfg->false_node_id;
    }
    if (next_node_id != -1) {
        // function to queue data for the next node
        queue_data_for_node(pipeline, next_node_id, data_record);
    }
    break;
}
```

**`docs/API.md`:**
```markdown
### Decision Node

A `decision` node routes incoming data to one of two outputs based on a condition.

**Configuration:**

- `condition`: A string in `"field_name==value"` format. The condition to evaluate.
- `true_node_id`: The `id` of the node to send data to if the condition is true.
- `false_node_id`: The `id` of the node to send data to if the condition is false.

**Example:**

```json
{
  "id": 5,
  "name": "Check Status",
  "type": "decision",
  "config": {
    "condition": "status_code==200",
    "true_node_id": 6,
    "false_node_id": 7
  }
}
```
